:root {
  --color-card-bg: #fdfaf5;
  --color-header-bg: #2d5a27;
  --color-header-text: #e8f5e4;
  --color-badge-bg: #1a3d16;
  --color-badge-text: #a8d5a2;
  --color-status-open: #4caf50;
  --color-date-text: #b8d8b4;
  --color-trail-name: #1e3a1a;
  --color-distance: #5a8a54;
  --color-tag-bg: #e8f0e6;
  --color-tag-text: #3a6235;
  --color-tag-border: #c2d9be;
  --color-section-bg: #f4f8f2;
  --color-condition-label: #6b8f66;
  --color-condition-border: #d4e8d0;
  --color-good: #2e7d32;
  --color-good-bg: #e8f5e9;
  --color-warn: #e65100;
  --color-warn-bg: #fff3e0;
  --color-footer-bg: #edf3eb;
  --color-footer-border: #c8ddc4;
  --color-note-label: #3a6235;
  --color-note-text: #4a5e48;
  --color-reported: #8aab86;
  --color-icon-bg: #ddeedd;
}

article.trail-card {
  width: 460px;
  background-color: var(--color-card-bg);
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--color-condition-border);
  font-size: 14px;
}

.trail-header {
  background-color: var(--color-header-bg);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.trail-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--color-badge-text);
}

.trail-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.trail-date {
  color: var(--color-date-text);
  font-size: 12px;
}

.trail-status.open {
  background-color: var(--color-status-open);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 3px 8px;
  border-radius: 10px;
}

.trail-info {
  padding: 14px 16px 10px;
}

.trail-name-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}

.trail-name {
  font-size: 19px;
  font-weight: 700;
  color: var(--color-trail-name);
  margin: 0;
  line-height: 1.2;
}

.trail-distance {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-distance);
}

.trail-tags {
  display: flex;
  gap: 6px;
}

.tag {
  background-color: var(--color-tag-bg);
  color: var(--color-tag-text);
  border: 1px solid var(--color-tag-border);
  border-radius: 6px;
  padding: 3px 9px;
  font-size: 12px;
  font-weight: 500;
}

.conditions-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 10px 16px;
  background-color: var(--color-section-bg);
  border-top: 1px solid var(--color-condition-border);
  border-bottom: 1px solid var(--color-condition-border);
}

.condition-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 6px;
  background-color: var(--color-card-bg);
  border-radius: 10px;
  border: 1px solid var(--color-condition-border);
}

.condition-icon {
  font-size: 20px;
  line-height: 1;
}

.condition-label {
  font-size: 11px;
  color: var(--color-condition-label);
  font-weight: 500;
}

.condition-value.good {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-good);
  background-color: var(--color-good-bg);
  padding: 2px 7px;
  border-radius: 8px;
}

.condition-value.warn {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-warn);
  background-color: var(--color-warn-bg);
  padding: 2px 7px;
  border-radius: 8px;
}

.trail-footer {
  background-color: var(--color-footer-bg);
  border-top: 1px solid var(--color-footer-border);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ranger-note {
  display: flex;
  align-items: center;
  gap: 6px;
}

.note-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-note-label);
}

.note-text {
  font-size: 12px;
  color: var(--color-note-text);
}

.reported-by {
  font-size: 11px;
  color: var(--color-reported);
  font-weight: 500;
}
